add_filter( 'woocommerce_quantity_input_args', 'perfectpixel_min_amount_quantity_args', 10, 2 );
add_action( 'woocommerce_check_cart_items', 'perfectpixel_min_amount_check_cart' );

function perfectpixel_min_amount_min_qty( $product ) {
	$ids   = wp_parse_id_list( '{{min_amount_product_ids}}' );
	$id    = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();
	$price = (float) $product->get_price();
	if ( ! in_array( $id, $ids, true ) || $price <= 0 ) {
		return 0;
	}
	return (int) ceil( (float) '{{min_amount_value}}' / $price );
}

function perfectpixel_min_amount_quantity_args( $args, $product ) {
	$min = perfectpixel_min_amount_min_qty( $product );
	if ( $min > 1 ) {
		$args['min_value'] = $min;
		if ( ! is_cart() ) {
			$args['input_value'] = max( $min, (int) ( $args['input_value'] ?? 1 ) );
		}
	}
	return $args;
}

function perfectpixel_min_amount_check_cart() {
	foreach ( WC()->cart->get_cart() as $item ) {
		$product = $item['data'];
		$min     = perfectpixel_min_amount_min_qty( $product );
		if ( $min > 1 && $item['quantity'] < $min ) {
			wc_add_notice( sprintf( esc_html( '{{min_amount_message}}' ), esc_html( $product->get_name() ), wc_price( (float) '{{min_amount_value}}' ) ), 'error' );
		}
	}
}
